Perhaps just for the sake of testing, a use case could look like this: 
```c#
logger.Log(LogLevel.Information, 0, state: new WithNullValue(), exception: null, formatter: (a, b) => string.Empty);
```
Where WithNullValue is:
```c#
    internal class WithNullValue : IReadOnlyList<KeyValuePair<string, object>>
    {
        int IReadOnlyCollection<KeyValuePair<string, object>>.Count { get; } = 1;

        KeyValuePair<string, object> IReadOnlyList<KeyValuePair<string, object>>.this[int index]
        {
            get
            {
                if (index == 0)
                {
                    return new KeyValuePair<string, object>("KeyForNull", null);
                }

                throw new ArgumentOutOfRangeException(nameof(index));
            }
        }

        IEnumerator<KeyValuePair<string, object>> IEnumerable<KeyValuePair<string, object>>.GetEnumerator()
        {
            yield return new KeyValuePair<string, object>("KeyForNull", null);
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return ((IEnumerable<KeyValuePair<string, object>>)this).GetEnumerator();
        }
    }
```
